// Each function returns the parsed response body and throws an Error carrying
// the server's message on a non-200 response.

const BASE_URL = '/api/bible/niv';

async function fetchJson(url) {
    const res = await fetch(url);
    const body = await res.json().catch(() => null);
    if (!res.ok) {
        throw new Error(body?.error || `Bible API request failed (${res.status})`);
    }
    return body;
}

/** @returns {Promise<{ version: string, books: Array<{ name: string, chapterCount: number }> }>} */
export function fetchBibleBooks() {
    return fetchJson(`${BASE_URL}/books`);
}

/** @returns {Promise<{ version: string, book: string, chapters: Array<{ chapter: number, verseCount: number }> }>} */
export function fetchBibleChapters(book) {
    return fetchJson(`${BASE_URL}/books/${encodeURIComponent(book)}/chapters`);
}

/** @returns {Promise<{ version: string, book: string, chapter: number, verses: Array<{ verse: number, text: string }> }>} */
export function fetchBibleVerses(book, chapter) {
    return fetchJson(
        `${BASE_URL}/books/${encodeURIComponent(book)}/chapters/${encodeURIComponent(chapter)}/verses`,
    );
}
"}

{"path":"/data/repos/opt-work/wpa-be-admin-74e95f20/flow2/ui/src/components/ScripturePicker.jsx","content":"import React, { useState, useEffect } from 'react';
import { Check } from 'lucide-react';
import { fetchBibleBooks, fetchBibleChapters, fetchBibleVerses } from '../api/bibleApi';

const ScripturePicker = ({ onSelect, onCancel, initialSelection }) => {
    // Initialize state from initialSelection if provided
    const [selectedBook, setSelectedBook] = useState(initialSelection?.book || null);
    const [selectedChapter, setSelectedChapter] = useState(
        initialSelection?.chapter != null ? Number(initialSelection.chapter) : null
    );
    const [selectedVerses, setSelectedVerses] = useState(initialSelection?.verses || {}); // { verseNum: text }
    const [title, setTitle] = useState(initialSelection?.title || '');
    const [lastClickedVerse, setLastClickedVerse] = useState(null);

    // Bible data loaded on demand from the NIV Bible API: books on open,
    // then chapters for the selected book and verses for the chapter.
    const [books, setBooks] = useState([]); // [{ name, chapterCount }]
    const [chapters, setChapters] = useState([]); // [{ chapter, verseCount }]
    const [chapterVerses, setChapterVerses] = useState([]); // [{ verse, text }]
    const [loadingBooks, setLoadingBooks] = useState(false);
    const [loadingChapters, setLoadingChapters] = useState(false);
    const [loadingVerses, setLoadingVerses] = useState(false);
    const [loadError, setLoadError] = useState(null);

    // Initial state set via useState above.
    // Since component remounts on open, we don't need to listen for prop changes.

    useEffect(() => {
        let ignore = false;
        setLoadingBooks(true);
        fetchBibleBooks()
            .then((data) => {
                if (!ignore) setBooks(data.books);
            })
            .catch((err) => {
                if (!ignore) setLoadError(err.message);
            })
            .finally(() => {
                if (!ignore) setLoadingBooks(false);
            });
        return () => { ignore = true; };
    }, []);

    useEffect(() => {
        if (!selectedBook) {
            setChapters([]);
            return;
        }
        let ignore = false;
        setLoadingChapters(true);
        fetchBibleChapters(selectedBook)
            .then((data) => {
                if (!ignore) setChapters(data.chapters);
            })
            .catch((err) => {
                if (!ignore) setLoadError(err.message);
            })
            .finally(() => {
                if (!ignore) setLoadingChapters(false);
            });
        return () => { ignore = true; };
    }, [selectedBook]);

    useEffect(() => {
        if (!selectedBook || selectedChapter == null) {
            setChapterVerses([]);
            return;
        }
        let ignore = false;
        setLoadingVerses(true);
        fetchBibleVerses(selectedBook, selectedChapter)
            .then((data) => {
                if (!ignore) setChapterVerses(data.verses);
            })
            .catch((err) => {
                if (!ignore) setLoadError(err.message);
            })
            .finally(() => {
                if (!ignore) setLoadingVerses(false);
            });
        return () => { ignore = true; };
    }, [selectedBook, selectedChapter]);

    const handleBookSelect = (book) => {
        if (selectedBook === book) return;
        setLoadError(null);
        setSelectedBook(book);
        setSelectedChapter(null);
        setSelectedVerses({});
        setLastClickedVerse(null);
    };

    const handleChapterSelect = (ch) => {
        if (selectedChapter === ch) return;
        setLoadError(null);
        setSelectedChapter(ch);
        setSelectedVerses({});
        setLastClickedVerse(null);
    };

    const handleVerseClick = (vNum, text, e) => {
        if (e.shiftKey && lastClickedVerse !== null) {
            const start = Math.min(lastClickedVerse, vNum);
            const end = Math.max(lastClickedVerse, vNum);

            const newVerses = { ...selectedVerses };

            // Add all verses in range
            chapterVerses.forEach(({ verse, text: verseText }) => {
                if (verse >= start && verse <= end) {
                    newVerses[String(verse)] = verseText;
                }
            });
            setSelectedVerses(newVerses);
        } else {
            toggleVerse(vNum, text);
            setLastClickedVerse(vNum);
        }
    };

    const toggleVerse = (verseNum, text) => {
        const key = String(verseNum);
        const newVerses = { ...selectedVerses };
        if (newVerses[key]) {
            delete newVerses[key];
        } else {
            newVerses[key] = text;
        }
        setSelectedVerses(newVerses);
    };
"}

