{"path":"/tmp/check-bible-api.mjs","content":"// Live probe: starts the real server.js, exercises the Bible API over HTTP,
// then shuts the server down. Usage: node /tmp/check-bible-api.mjs
import { spawn } from 'node:child_process';

const BASE = 'http://127.0.0.1:3001';
const server = spawn('node', ['server.js'], {
    cwd: '/data/repos/opt-work/wpa-be-admin-74e95f20/flow2',
    stdio: ['ignore', 'pipe', 'pipe'],
});
let serverLog = '';
server.stdout.on('data', (d) => { serverLog += d; });
server.stderr.on('data', (d) => { serverLog += d; });

async function waitForServer() {
    for (let i = 0; i < 50; i++) {
        try {
            const res = await fetch(`${BASE}/api/bible/niv/books`);
            if (res.ok) return;
        } catch { /* not up yet */ }
        await new Promise((r) => setTimeout(r, 200));
    }
    throw new Error(`Server did not come up. Log:\n${serverLog}`);
}

let failures = 0;
function check(label, condition, detail = '') {
    console.log(`${condition ? 'PASS' : 'FAIL'} ${label}${detail ? ` — ${detail}` : ''}`);
    if (!condition) failures++;
}

try {
    await waitForServer();
    console.log('--- server log (first lines) ---');
    console.log(serverLog.split('\n').slice(0, 4).join('\n'));

    // 1. All books
    let res = await fetch(`${BASE}/api/bible/niv/books`);
    let body = await res.json();
    check('GET /api/bible/niv/books -> 200', res.status === 200, `status ${res.status}`);
    check('66 books, Genesis first (50 ch), Revelation last',
        body.books?.length === 66 && body.books[0].name === 'Genesis'
        && body.books[0].chapterCount === 50 && body.books.at(-1).name === 'Revelation',
        `count=${body.books?.length} first=${JSON.stringify(body.books?.[0])}`);
    check('Cache-Control set', (res.headers.get('cache-control') || '').includes('max-age=86400'),
        res.headers.get('cache-control'));

    // 2. Chapters for a book (URL-encoded, with space + number)
    res = await fetch(`${BASE}/api/bible/niv/books/${encodeURIComponent('1 Samuel')}/chapters`);
    body = await res.json();
    check('GET chapters for "1 Samuel" -> 31 chapters',
        res.status === 200 && body.book === '1 Samuel' && body.chapters?.length === 31,
        `status ${res.status} book=${body.book} count=${body.chapters?.length}`);

    res = await fetch(`${BASE}/api/bible/niv/books/Psalms/chapters`);
    body = await res.json();
    check('Psalms -> 150 chapters, ch.1 has 6 verses',
        body.chapters?.length === 150 && body.chapters[0].verseCount === 6,
        `count=${body.chapters?.length} ch1=${JSON.stringify(body.chapters?.[0])}`);

    // Case-insensitive + alias resolution through the real server
    res = await fetch(`${BASE}/api/bible/niv/books/psalm/chapters`);
    body = await res.json();
    check('"psalm" resolves to Psalms', res.status === 200 && body.book === 'Psalms', `book=${body.book}`);

    // 3. Verses for a book chapter
    res = await fetch(`${BASE}/api/bible/niv/books/John/chapters/3/verses`);
    body = await res.json();
    const v16 = body.verses?.find((v) => v.verse === 16);
    check('John 3 verses include 3:16 text',
        res.status === 200 && body.chapter === 3 && /For God so loved the world/.test(v16?.text || ''),
        `verses=${body.verses?.length}`);

    res = await fetch(`${BASE}/api/bible/niv/books/Genesis/chapters/1/verses`);
    body = await res.json();
    check('Genesis 1:1 exact text',
        body.verses?.[0]?.text === 'In the beginning God created the heavens and the earth.',
        body.verses?.[0]?.text);

    // Error cases
    res = await fetch(`${BASE}/api/bible/niv/books/Hezekiah/chapters`);
    body = await res.json();
    check('unknown book -> 404 {error}', res.status === 404 && !!body.error, `status ${res.status} ${body.error}`);

    res = await fetch(`${BASE}/api/bible/niv/books/Jude/chapters/2/verses`);
    check('Jude chapter 2 -> 404', res.status === 404, `status ${res.status}`);

    res = await fetch(`${BASE}/api/bible/niv/books/Genesis/chapters/abc/verses`);
    check('malformed chapter -> 400', res.status === 400, `status ${res.status}`);

    // Backwards compatibility: full-file endpoint still serves the whole Bible
    res = await fetch(`${BASE}/api/niv`);
    body = await res.json();
    check('GET /api/niv still returns full Bible (66 books)',
        res.status === 200 && Object.keys(body).length === 66, `status ${res.status}`);

    // UI is served by the same server (dist built)
    res = await fetch(`${BASE}/`);
    const html = await res.text();
    check('GET / serves the built UI', res.status === 200 && html.includes('<div id="root">'), `status ${res.status}`);
} finally {
    server.kill();
}

console.log(failures === 0 ? '\nALL CHECKS PASSED' : `\n${failures} CHECK(S) FAILED`);
process.exit(failures === 0 ? 0 : 1);
"}

