2|import { BibleServiceError } from '../services/bibleService.js';
3|
4|// Bible text is static for the life of the process, so responses can be
5|// cached by the browser instead of refetched on every picker open.
6|const CACHE_CONTROL = 'public, max-age=86400';
7|
8|/**
9| * Builds the NIV Bible router. Mount it at `/api/bible/niv`, giving:
10| *
11| * - GET /books                                    -> all books
12| * - GET /books/:book/chapters                     -> chapters for a book
13| * - GET /books/:book/chapters/:chapter/verses     -> verses for a chapter
14| *
15| * @param {import('../services/bibleService.js').BibleService|null} bibleService
16| *   When null (niv.json unavailable), every endpoint returns 503.
17| * @returns {import('express').Router}
18| */
19|export function createBibleRouter(bibleService) {
20|    const router = express.Router();
21|
22|    function handle(handler) {
23|        return (req, res) => {
24|            if (!bibleService) {
25|                return res.status(503).json({ error: 'NIV Bible data not available' });
26|            }
27|            try {
28|                res.set('Cache-Control', CACHE_CONTROL);
29|                return res.json(handler(req));
30|            } catch (error) {
31|                if (error instanceof BibleServiceError) {
32|                    return res.status(error.status).json({ error: error.message });
33|                }
34|                console.error('Error in Bible API:', error);
35|                return res.status(500).json({ error: error.message });
36|            }
37|        };
38|    }
39|
40|    // Get all books
41|    router.get('/books', handle(() => bibleService.getBooks()));
42|
43|    // Get chapters for a book
44|    router.get('/books/:book/chapters', handle((req) => bibleService.getChapters(req.params.book)));
45|
46|    // Get verses for a book chapter
47|    router.get(
48|        '/books/:book/chapters/:chapter/verses',
49|        handle((req) => bibleService.getVerses(req.params.book, req.params.chapter)),
50|    );
51|
52|    return router;
