10|        super(message);
11|        this.name = 'BibleServiceError';
12|        this.status = status;
13|    }
14|}
15|
16|function sortedNumericKeys(obj) {
17|    return Object.keys(obj).sort((a, b) => Number(a) - Number(b));
18|}
19|
20|/**
21| * Serves Bible lookups from parsed `niv.json` data shaped as
22| * `{ [book]: { [chapter]: { [verse]: text } } }`, with books in canonical
23| * order and chapter/verse keys as numeric strings.
24| */
25|export class BibleService {
26|    /**
27|     * @param {Object} bibleData - Parsed niv.json content
28|     * @param {{ version?: string }} [options]
29|     */
30|    constructor(bibleData, { version = 'NIV' } = {}) {
31|        if (!bibleData || typeof bibleData !== 'object' || Object.keys(bibleData).length === 0) {
32|            throw new Error('BibleService requires non-empty bible data');
33|        }
34|        this.bibleData = bibleData;
35|        this.version = version;
36|    }
37|
38|    /**
39|     * Resolves a requested book name to the canonical key in the data.
40|     * Matching is case-insensitive (ignoring surrounding whitespace) and the
41|     * singular "Psalm" resolves to "Psalms", matching populateBibleVerses.
42|     *
43|     * @param {string} book
44|     * @returns {string|null} Canonical book name, or null when unknown
45|     */
46|    resolveBookName(book) {
47|        if (typeof book !== 'string') return null;
48|        const requested = book.trim();
49|        if (!requested) return null;
50|        if (Object.hasOwn(this.bibleData, requested)) return requested;
51|
52|        const normalized = requested.toLowerCase();
53|        const alias = normalized === 'psalm' ? 'Psalms' : null;
54|        if (alias && Object.hasOwn(this.bibleData, alias)) return alias;
55|
56|        return Object.keys(this.bibleData).find(
57|            (name) => name.toLowerCase() === normalized,
58|        ) ?? null;
59|    }
60|
61|    /** @returns {{ version: string, books: Array<{ name: string, chapterCount: number }> }} */
62|    getBooks() {
63|        return {
64|            version: this.version,
65|            books: Object.keys(this.bibleData).map((name) => ({
66|                name,
67|                chapterCount: Object.keys(this.bibleData[name]).length,
68|            })),
69|        };
70|    }
71|
72|    /**
73|     * @param {string} book - Book name as requested (canonical name is returned)
74|     * @returns {{ version: string, book: string, chapters: Array<{ chapter: number, verseCount: number }> }}
75|     */
76|    getChapters(book) {
77|        const canonicalBook = this.#requireBook(book);
78|        const chapters = this.bibleData[canonicalBook];
79|        return {
80|            version: this.version,
81|            book: canonicalBook,
82|            chapters: sortedNumericKeys(chapters).map((chapter) => ({
83|                chapter: Number(chapter),
84|                verseCount: Object.keys(chapters[chapter]).length,
85|            })),
86|        };
87|    }
88|
89|    /**
90|     * @param {string} book - Book name as requested (canonical name is returned)
91|     * @param {string|number} chapter - Chapter number (positive integer)
92|     * @returns {{ version: string, book: string, chapter: number, verses: Array<{ verse: number, text: string }> }}
93|     */
94|    getVerses(book, chapter) {
95|        const canonicalBook = this.#requireBook(book);
96|        const chapterNumber = this.#parseChapter(chapter);
97|        const verses = this.bibleData[canonicalBook][String(chapterNumber)];
98|        if (!verses) {
99|            throw new BibleServiceError(
100|                `Chapter not found: ${canonicalBook} ${chapterNumber}`,
101|                404,
102|            );
103|        }
104|        return {
105|            version: this.version,
106|            book: canonicalBook,
107|            chapter: chapterNumber,
108|            verses: sortedNumericKeys(verses).map((verse) => ({
109|                verse: Number(verse),
110|                text: verses[verse],
111|            })),
112|        };
113|    }
114|
115|    #requireBook(book) {
116|        const canonicalBook = this.resolveBookName(book);
117|        if (!canonicalBook) {
118|            throw new BibleServiceError(`Book not found: ${book}`, 404);
119|        }
120|        return canonicalBook;
121|    }
122|
123|    #parseChapter(chapter) {
124|        const raw = typeof chapter === 'string' ? chapter.trim() : chapter;
125|        const isPositiveInteger =
126|            (typeof raw === 'number' && Number.isInteger(raw) && raw > 0) ||
127|            (typeof raw === 'string' && /^[0-9]+$/.test(raw) && Number(raw) > 0);
128|        if (!isPositiveInteger) {
129|            throw new BibleServiceError('Chapter must be a positive integer', 400);
130|        }
131|        return Number(raw);
132|    }
