        const endVerse = givenEndVerse ?? this.#lastVerse(book, endChapter);

        const requireVerse = (verses, chapter, verse) => {
            if (verses[String(verse)] === undefined) {
                throw new BibleServiceError(
                    `Verse not found: ${book} ${chapter}:${verse}`,
