// Usage: node /tmp/check-passage-api.mjs
import { spawn } from 'node:child_process';

const BASE = 'http://127.0.0.1:3001';
const server = spawn('node', ['server.js'], {
    cwd: '/data/repos/opt-work/wpa-be-admin-74e95f20/flow2',
    stdio: ['ignore', 'pipe', 'pipe'],
});
let log = '';
server.stdout.on('data', (d) => { log += d; });
server.stderr.on('data', (d) => { log += d; });

async function waitForServer() {
    for (let i = 0; i < 50; i++) {
        try {
            const res = await fetch(`${BASE}/api/bible/niv/books`);
            if (res.ok) return;
        } catch { /* not up yet */ }
        await new Promise((r) => setTimeout(r, 200));
    }
    throw new Error(`Server did not come up:\n${log}`);
}

let failures = 0;
const check = (label, ok, detail = '') => {
    console.log(`${ok ? 'PASS' : 'FAIL'} ${label}${detail ? ` — ${detail}` : ''}`);
    if (!ok) failures++;
};
const passage = async (ref) => {
    const res = await fetch(`${BASE}/api/bible/niv/passage?ref=${encodeURIComponent(ref)}`);
    const body = await res.json();
    return { status: res.status, body };
};
const coords = (body) => body.verses.map((v) => `${v.chapter}:${v.verse}`).join(',');

try {
    await waitForServer();

    let { status, body } = await passage('romans 4:1-6');
    check('romans 4:1-6 -> 6 verses', status === 200 && body.verses.length === 6 && coords(body) === '4:1,4:2,4:3,4:4,4:5,4:6', `${status} ${body.reference}`);
    console.log('  v1:', body.verses[0].text);
    console.log('  v6:', body.verses.at(-1).text);

    ({ status, body } = await passage('John 3:16'));
    check('John 3:16 single', status === 200 && body.verses.length === 1 && /For God so loved/.test(body.verses[0].text), body.reference);

    ({ status, body } = await passage('Romans 4'));
    check('Romans 4 whole chapter -> 25', status === 200 && body.verses.length === 25, body.reference);

    ({ status, body } = await passage('Romans 4:23-5:2'));
    check('cross-chapter 4:23-5:2', status === 200 && coords(body) === '4:23,4:24,4:25,5:1,5:2' && body.chapter === null, `${body.reference} chapters=${body.chapters}`);

    ({ status, body } = await passage('Romans 4:1-3, 5'));
    check('multiple ranges 4:1-3,5', status === 200 && coords(body) === '4:1,4:2,4:3,4:5', body.reference);

    for (const [ref, book] of [['Rom. 4:1', 'Romans'], ['Ps 23:1', 'Psalms'], ['1 Cor. 13:4', '1 Corinthians'], ['II Cor 5:17', '2 Corinthians'], ['1Sam 1:1', '1 Samuel'], ['Judg 1:1', 'Judges'], ['Jud 1:1', 'Jude'], ['Phil 4:13', 'Philippians'], ['Phlm 1:1', 'Philemon'], ['Song 2:7', 'Song of Solomon']]) {
        const r = await passage(ref);
        check(`abbrev "${ref}" -> ${book}`, r.status === 200 && r.body.book === book, `got ${r.body.book || r.body.error}`);
    }

    ({ status, body } = await passage('Romans 4:1-99'));
    check('out-of-range end -> 404 (no clamp)', status === 404 && !!body.error, body.error);

    ({ status, body } = await passage('Romans 4:6-1'));
    check('reversed range -> 400', status === 400 && !!body.error, body.error);

    const res = await fetch(`${BASE}/api/bible/niv/passage`);
    check('missing ref -> 400', res.status === 400, `status ${res.status}`);

    ({ status, body } = await passage('Hezekiah 1:1'));
    check('unknown book -> 404', status === 404 && !!body.error, body.error);
} finally {
    server.kill();
}
console.log(failures === 0 ? '\nALL CHECKS PASSED' : `\n${failures} CHECK(S) FAILED`);
process.exit(failures === 0 ? 0 : 1);
"}
